def parity(preds, groups):
    totals, positives = {}, {}
    for p, g in zip(preds, groups):
        totals[g] = totals.get(g, 0) + 1
        positives[g] = positives.get(g, 0) + p
    rates = {g: round(positives[g] / totals[g], 4) for g in totals}
    diff = round(max(rates.values()) - min(rates.values()), 4)
    return rates, diff

