def equalized_odds_diff(y_true, y_pred, groups):
    tpr, fpr = [], []
    for g in set(groups):
        rows = [(t, p) for t, p, gg in zip(y_true, y_pred, groups) if gg == g]
        pos = [p for t, p in rows if t == 1]
        neg = [p for t, p in rows if t == 0]
        if pos:
            tpr.append(sum(pos) / len(pos))
        if neg:
            fpr.append(sum(neg) / len(neg))
    gap_t = max(tpr) - min(tpr) if tpr else 0.0
    gap_f = max(fpr) - min(fpr) if fpr else 0.0
    return round(max(gap_t, gap_f), 4)

