def counterfactual_gaps(score_fn, template, names, runs, tolerance):
    means = {}
    for name in names:
        text = template.format(name=name)
        scores = [score_fn(text) for _ in range(runs)]
        means[name] = round(sum(scores) / runs, 3)
    gap = max(means.values()) - min(means.values())
    return means, gap <= tolerance + 1e-9
